from globmatch import matches


def test_star_crosses_slash():
    assert matches("*.py", "src/app.py") is True


def test_double_star_recurses():
    assert matches("**/*.py", "a/b/c.py") is True


def test_pattern_matches_anywhere():
    assert matches("py", "app.py") is True
